//! The model's scores are those of the research implementation, on hand-written sentences.
//!
//! `tests/fixtures/sentences.tsv`: 343 sentences written for this test (family, sentence, intended correction; 126 hold
//! one error). `tests/fixtures/sentences.frc-infer-v14.jsonl`: what fr-check-infer (commit cc7d94e, itself checked
//! against PyTorch) gives for them with the H1 model, regenerated by `tools/parity.sh`:
//!   frc-infer v14 sentences.jsonl OUT --model model.frcm --frc-ignore SPELL,TYPO,SPACE,NBSP,DUP,DOUBLE
//!     --lexicon lexicon.tsv --resources resources --frc-lex lex
//! Pass: same words and skip decision for every sentence, every per-word score within 1e-5 (the code is the same port,
//! so the difference is expected to be 0). Skipped when the data files are not installed.
mod common;
use serde_json::Value;
use vaugelas::report::Vaugelas;

#[test]
fn scores_identical_to_frc_infer_v14() {
    let Some(d) = common::load() else { return };
    let vg = Vaugelas::new(&d);
    let tsv = common::fixture("sentences.tsv");
    let sentences: Vec<&str> = tsv.lines().skip(1).map(|l| l.split('\t').nth(1).unwrap()).collect();
    let refs: Vec<Value> = common::fixture("sentences.frc-infer-v14.jsonl").lines().map(|l| serde_json::from_str(l).unwrap()).collect();
    assert_eq!(sentences.len(), refs.len());
    let (mut words_differ, mut skip_differ, mut tokens, mut over, mut max) = (0, 0, 0usize, 0usize, 0f64);
    for (s, r) in sentences.iter().zip(&refs) {
        let got = vg.scorer.score_sentence(s).unwrap();
        let rw: Vec<&str> = r["words"].as_array().unwrap().iter().map(|w| w.as_str().unwrap()).collect();
        if got.words != rw { words_differ += 1; eprintln!("words differ: {s}\n  {:?}\n  {rw:?}", got.words); continue; }
        if got.skip.map(|k| k.name()) != r["skip"].as_str() { skip_differ += 1; eprintln!("skip differs: {s}"); continue; }
        let rs: Vec<f64> = r["scores"].as_array().map(|a| a.iter().map(|x| x.as_f64().unwrap()).collect()).unwrap_or_default();
        assert_eq!(got.scores.len(), rs.len(), "{s}");
        for ((a, _), b) in got.scores.iter().zip(&rs) {
            let dlt = (a - b).abs();
            tokens += 1;
            max = max.max(dlt);
            if dlt > 1e-5 { over += 1; eprintln!("score differs by {dlt:e}: {s}"); }
        }
    }
    eprintln!("parity: {} sentences, {tokens} scored words, max |diff| {max:e}, {over} over 1e-5, words differ {words_differ}, skip differs {skip_differ}",
              sentences.len());
    assert_eq!((words_differ, skip_differ, over), (0, 0, 0));
}
